graph TD
    CWD["/project/src/components/"] --> F1["CLAUDE.md ← 组件级"]
    F1 --> UP1["/project/src/"]
    UP1 --> F2["CLAUDE.md ← 源码级"]
    F2 --> UP2["/project/"]
    UP2 --> F3["CLAUDE.md ← 项目级"]
    F3 --> UP3["/"]
